/** Fixture stand-in for the parts of `express` the typed rule tests read: the response a door writes cookies and headers through. */
export interface CookieOptions { httpOnly?: boolean; secure?: boolean; sameSite?: boolean | "lax" | "strict" | "none"; maxAge?: number; domain?: string; path?: string }
export interface Response {
    cookie(name: string, value: string, options?: CookieOptions): this
    clearCookie(name: string, options?: CookieOptions): this
    setHeader(name: string, value: string | readonly string[]): this
    append(field: string, value?: string | string[]): this
    header(field: string, value?: string | string[]): this
}
